import {
  type ReactNode,
  type KeyboardEvent,
  useState,
  useRef,
  useEffect,
  useCallback,
  createContext,
  useContext,
} from 'react';

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

/* ---- Context ---- */

type DropdownMenuContextValue = {
  open: boolean;
  setOpen: (v: boolean) => void;
};

const DropdownMenuContext = createContext<DropdownMenuContextValue | null>(null);

function useDropdownMenu() {
  const ctx = useContext(DropdownMenuContext);
  if (!ctx) throw new Error('DropdownMenu components must be used within <DropdownMenu>');
  return ctx;
}

/* ---- Root ---- */

export type DropdownMenuProps = {
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  children: ReactNode;
  className?: string;
};

export function DropdownMenu({
  open: controlledOpen,
  onOpenChange,
  children,
  className,
}: DropdownMenuProps) {
  const [internalOpen, setInternalOpen] = useState(false);
  const rootRef = useRef<HTMLDivElement>(null);

  const open = controlledOpen ?? internalOpen;

  const setOpen = useCallback(
    (v: boolean) => {
      onOpenChange ? onOpenChange(v) : setInternalOpen(v);
    },
    [onOpenChange],
  );

  useEffect(() => {
    if (!open) return;
    const handler = (e: MouseEvent) => {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open, setOpen]);

  useEffect(() => {
    if (!open) return;
    const handler = (e: globalThis.KeyboardEvent) => {
      if (e.key === 'Escape') setOpen(false);
    };
    document.addEventListener('keydown', handler);
    return () => document.removeEventListener('keydown', handler);
  }, [open, setOpen]);

  return (
    <DropdownMenuContext.Provider value={{ open, setOpen }}>
      <div ref={rootRef} className={cn('dropdown-menu', className)}>
        {children}
      </div>
    </DropdownMenuContext.Provider>
  );
}

/* ---- Trigger ---- */

export function DropdownMenuTrigger({
  children,
  className,
}: {
  children: ReactNode;
  className?: string;
}) {
  const { open, setOpen } = useDropdownMenu();

  const handleKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'ArrowDown' || e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      setOpen(true);
    }
  };

  return (
    <div
      role="button"
      tabIndex={0}
      aria-expanded={open}
      aria-haspopup="menu"
      className={cn('dropdown-menu__trigger', className)}
      onClick={() => setOpen(!open)}
      onKeyDown={handleKeyDown}
    >
      {children}
    </div>
  );
}

/* ---- Content ---- */

export type DropdownMenuContentProps = {
  side?: 'top' | 'bottom';
  align?: 'start' | 'end';
  children: ReactNode;
  className?: string;
};

export function DropdownMenuContent({
  side = 'bottom',
  align = 'start',
  children,
  className,
}: DropdownMenuContentProps) {
  const { open } = useDropdownMenu();
  if (!open) return null;

  return (
    <div
      role="menu"
      className={cn(
        'dropdown-menu__content',
        `dropdown-menu__content--${side}`,
        `dropdown-menu__content--align-${align}`,
        className,
      )}
    >
      {children}
    </div>
  );
}

/* ---- Label ---- */

export function DropdownMenuLabel({
  children,
  className,
}: {
  children: ReactNode;
  className?: string;
}) {
  return <div className={cn('dropdown-menu__label', className)}>{children}</div>;
}

/* ---- Group ---- */

export function DropdownMenuGroup({
  children,
  className,
}: {
  children: ReactNode;
  className?: string;
}) {
  return <div role="group" className={className}>{children}</div>;
}

/* ---- Item ---- */

export type DropdownMenuItemProps = {
  variant?: 'default' | 'destructive';
  disabled?: boolean;
  onSelect?: () => void;
  children: ReactNode;
  className?: string;
};

export function DropdownMenuItem({
  variant = 'default',
  disabled = false,
  onSelect,
  children,
  className,
}: DropdownMenuItemProps) {
  const { setOpen } = useDropdownMenu();

  const handleClick = () => {
    if (disabled) return;
    onSelect?.();
    setOpen(false);
  };

  const handleKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      handleClick();
    }
  };

  return (
    <div
      role="menuitem"
      tabIndex={disabled ? -1 : 0}
      aria-disabled={disabled || undefined}
      className={cn(
        'dropdown-menu__item',
        variant === 'destructive' && 'dropdown-menu__item--destructive',
        disabled && 'dropdown-menu__item--disabled',
        className,
      )}
      onClick={handleClick}
      onKeyDown={handleKeyDown}
    >
      {children}
    </div>
  );
}

/* ---- Shortcut ---- */

export function DropdownMenuShortcut({
  children,
  className,
}: {
  children: ReactNode;
  className?: string;
}) {
  return <span className={cn('dropdown-menu__shortcut', className)}>{children}</span>;
}

/* ---- Separator ---- */

export function DropdownMenuSeparator({ className }: { className?: string }) {
  return <div role="separator" className={cn('dropdown-menu__separator', className)} />;
}

/* -------------------------------------------------------------------------
   Dropdown Menu

   Action menu triggered by a button. Floating panel with items.
   Composable: Trigger + Content > Label + Group + Item + Separator

   Parts: .dropdown-menu, .dropdown-menu__trigger, .dropdown-menu__content,
          .dropdown-menu__item, .dropdown-menu__label,
          .dropdown-menu__separator, .dropdown-menu__shortcut
   ------------------------------------------------------------------------- */

/* ---- Root ---- */

.dropdown-menu {
  position: relative;
  display: inline-flex;
}

/* ---- Trigger ---- */

.dropdown-menu__trigger {
  display: inline-flex;
  align-items: center;
  cursor: pointer;
}

/* ---- Content (floating panel) ---- */

.dropdown-menu__content {
  position: absolute;
  z-index: var(--z-index-20);
  min-width: 192px;
  overflow: hidden;
  border: var(--stroke-hairline) solid var(--border);
  border-radius: var(--radius-lg);
  background-color: var(--popover);
  color: var(--popover-foreground);
  box-shadow: var(--shadow-md);
  padding: var(--spacing-1, 4px);
  transform-origin: var(--dropdown-menu-origin, top);
  animation: dropdown-menu-in var(--duration-200) var(--easing-out);
}

.dropdown-menu__content--bottom {
  top: calc(100% + var(--spacing-1, 4px));
  --dropdown-menu-origin: top;
}

.dropdown-menu__content--top {
  bottom: calc(100% + var(--spacing-1, 4px));
  --dropdown-menu-origin: bottom;
}

.dropdown-menu__content--align-start { left: 0; }
.dropdown-menu__content--align-end { right: 0; }

@keyframes dropdown-menu-in {
  from {
    opacity: 0;
    transform: scale(0.96) translateY(-2px);
  }
  to {
    opacity: 1;
    transform: scale(1) translateY(0);
  }
}

/* ---- Label ---- */

.dropdown-menu__label {
  padding: var(--spacing-2, 8px) var(--spacing-2, 8px) var(--spacing-1, 4px);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  color: var(--popover-foreground);
}

/* ---- Item ---- */

.dropdown-menu__item {
  display: flex;
  align-items: center;
  gap: var(--spacing-2, 8px);
  width: 100%;
  padding: var(--spacing-2, 8px);
  border: none;
  border-radius: var(--radius-sm);
  background: none;
  color: var(--popover-foreground);
  font-family: inherit;
  font-size: var(--font-size-sm);
  line-height: 1;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background-color var(--duration-100) var(--easing-in-out);
}

.dropdown-menu__item:hover {
  background-color: var(--accent);
  color: var(--accent-foreground);
}

.dropdown-menu__item:focus-visible {
  outline: var(--focus-ring-width, 2px) solid var(--focus-ring-color);
  outline-offset: -2px;
  border-radius: var(--radius-sm);
}

.dropdown-menu__item--disabled {
  color: var(--muted-foreground);
  cursor: not-allowed;
  pointer-events: none;
}

.dropdown-menu__item--destructive {
  color: var(--destructive);
}

.dropdown-menu__item--destructive:hover {
  background-color: var(--destructive);
  color: var(--destructive-foreground);
}

/* ---- Item icon ---- */

.dropdown-menu__item-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 1em;
  height: 1em;
}

.dropdown-menu__item-icon svg {
  width: 100%;
  height: 100%;
}

/* ---- Shortcut ---- */

.dropdown-menu__shortcut {
  margin-left: auto;
  font-size: var(--font-size-xs);
  color: var(--muted-foreground);
  letter-spacing: var(--letter-spacing-wide);
}

/* ---- Separator ---- */

.dropdown-menu__separator {
  height: var(--stroke-hairline);
  margin: var(--spacing-1, 4px) calc(-1 * var(--spacing-1, 4px));
  background-color: var(--border);
}

/* ---- Reduced motion ---- */

@media (prefers-reduced-motion: reduce) {
  .dropdown-menu__item {
    transition-duration: 0ms;
  }

  .dropdown-menu__content {
    animation-duration: 0ms;
  }
}
